editor=r'''using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public class EMPhaseChainObserver:MonoBehaviour {public Component controller;public Component ledger;public int fps;private int prior;private List<string> rows=new List<string>();static string Read(object o,string n){return Convert.ToString(o.GetType().GetField(n).GetValue(o),System.Globalization.CultureInfo.InvariantCulture);}static Component Ref(Component o,string n){return o?(Component)o.GetType().GetField(n).GetValue(o):null;}void Awake(){Time.timeScale=1;Time.captureDeltaTime=1f/fps;}void LateUpdate(){try{int frame=int.Parse(Read(controller,"Frame"));if(frame<=prior)return;prior=frame;var row=new List<string>{frame.ToString(),Read(ledger,"Code"),Read(ledger,"Calls")};foreach(string name in new[]{"Primary","LateAdded"}){var c=Ref(controller,name);row.Add(c?"1":"0");row.Add(c?(((Behaviour)c).enabled?"1":"0"):"-1");row.Add(c?(c.gameObject.activeSelf?"1":"0"):"-1");foreach(string n in new[]{"Starts","Updates","Lates","Enables","Disables","ReturnedStart","ReturnedEnable"})row.Add(c?Read(c,n):"-1");foreach(string slot in new[]{"StartLeaf","EnableLeaf"}){var leaf=Ref(c,slot);row.Add(leaf?"1":"0");foreach(string n in new[]{"Starts","Updates","Lates","Enables","Disables"})row.Add(leaf?Read(leaf,n):"-1");}}rows.Add("["+string.Join(",",row)+"]");if(frame>=24){File.WriteAllText(Environment.GetEnvironmentVariable("EM_PHASE_CHAIN_OUTPUT"),"{\"status\":\"CAPTURED\",\"rows\":["+string.Join(",",rows)+"]}");EditorApplication.Exit(0);}}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}
public static class EMPhaseChainProbe {public static void Run(){try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string prefix=Environment.GetEnvironmentVariable("EM_PHASE_CHAIN_RESTORED")=="1"?"Restored":"";var asm=typeof(PhaseChainController).Assembly;var ct=asm.GetType(prefix+"PhaseChainController");var lt=asm.GetType(prefix+"PhaseChainLedger");var ledger=new GameObject("Chain ledger").AddComponent(lt);var c=new GameObject("Chain controller").AddComponent(ct);ct.GetField("Ledger").SetValue(c,ledger);foreach(var pair in new[]{new KeyValuePair<string,int>("PhaseChainController",-100),new KeyValuePair<string,int>("PhaseChainSpawner",0),new KeyValuePair<string,int>("PhaseChainLeaf",100)}){string path="Assets/EngineMigratorPhaseChainProbe/"+prefix+pair.Key+".cs";MonoImporter.SetExecutionOrder(AssetDatabase.LoadAssetAtPath<MonoScript>(path),pair.Value);}var o=new GameObject("Chain observer").AddComponent<EMPhaseChainObserver>();MonoImporter.SetExecutionOrder(MonoScript.FromMonoBehaviour(o),10000);o.controller=c;o.ledger=ledger;o.fps=int.Parse(Environment.GetEnvironmentVariable("EM_PHASE_CHAIN_FPS"));Time.timeScale=1;Time.captureDeltaTime=1f/o.fps;EditorSettings.enterPlayModeOptionsEnabled=true;EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload|EnterPlayModeOptions.DisableSceneReload;var deadline=EditorApplication.timeSinceStartup+120;EditorApplication.update+=()=>{if(EditorApplication.timeSinceStartup>deadline)EditorApplication.Exit(2);};EditorApplication.EnterPlaymode();}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}
'''
